/* ── Tasks table + split-view shell styles (PR-B) ──────────────────────────────
   Extracted from TasksPage's inline <style> so both the standalone full-page
   host AND the split-view shell render identically. Every value resolves to a
   DESIGN.md token; the only literal px are layout dimensions (sizes/radii) and
   the documented drawer width clamp (OD-P3-2).
   ──────────────────────────────────────────────────────────────────────────── */

/* ── Page head ── */
/* IA-1: the page head is the shared shell/PageHead.tsx (title + meta beside it, full-bleed —
   no maxWidth cap). The bespoke .page-head-row / .tasks-page-title / .tasks-count-line
   classes were removed; only the head-owned controls below remain. */

/* ── Content header (mockup `.content-header`) ──────────────────────────────────
   The list/DB-view header chrome: a single clean row = entity icon + title +
   count pill + right-aligned inline action. Pixel oracle:
   docs/design-mockups/ui-revamp/mock-shell-and-table.html `.content-header`.
   Every value resolves to a DESIGN.md token (crosswalk of the mockup's --ds-*). */
.content-header {
  display: flex; align-items: center; gap: 10px;
  min-height: 48px; margin-bottom: 16px;
  padding-bottom: 14px; border-bottom: 1px solid var(--border);
}
.content-header .ch-icon { color: var(--muted-foreground); display: inline-flex; flex: none; }
.content-header .ch-title {
  font-weight: 600; font-size: 24px; letter-spacing: -0.01em; color: var(--foreground);
  margin: 0; line-height: 1.2;
}
/* Count pill (mockup `.ch-count`) — small muted pill on the tertiary surface. */
.content-header .ch-count {
  font-size: 11px; font-weight: 600; color: var(--muted-foreground);
  background: var(--secondary); padding: 2px 9px; border-radius: 999px;
  flex: none; line-height: 1.4;
}
/* Overdue/blocked subtotals + clearable filter chips ride just after the pill. */
.content-header .ch-meta { display: inline-flex; align-items: center; gap: 10px; flex-wrap: wrap; }
/* Right-aligned inline action (mockup `.ch-action`) — pushed to the far edge. */
.content-header .ch-action { margin-left: auto; flex: none; }
/* Off-track subtotals (blocked / overdue) ride beside the count pill. */
.ch-submeta { color: var(--muted-foreground); font-size: 15px; }

/* ── Split-view grid (the push/squash master-detail, ADR-0007) ── */
.split {
  display: grid;
  grid-template-columns: minmax(0, 1fr) clamp(360px, 33vw, 480px); /* OD-P3-2 drawer width; minmax(0,1fr) not bare 1fr so wide card/table content can't stretch the track past the viewport (min-width:auto blowout) */
  align-items: start; gap: 12px;
  /* CONV (owner-directed 2026-06-17): the data workspace runs FULL-BLEED — no max-width cap.
     It fills PageFrame's 24px gutters, which equal the topbar's px-6 gutter, so the table's
     right edge aligns with the account chip (no detached 1/3-width content on wide monitors).
     Only the Task column (1fr) absorbs the extra width; the other columns are fixed-px, so
     nothing balloons. A generous safety cap guards absurd ultra-wide Task columns only. */
  max-width: 1760px;
}
.split.nodrawer { grid-template-columns: minmax(0, 1fr); }
/* Expanded focus mode: table hidden, drawer fills the row. */
.split.expanded { grid-template-columns: 1fr; }
.split.expanded .assembly { display: none; }

/* ── Card assembly (OD-P3-10/11) ── */
.assembly {
  background: var(--card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); /* 12px — card surface, OD-P3-10 */
  box-shadow: var(--shadow-rest); /* OD-P3-11 resting lift */
  overflow: hidden; min-width: 0;
}

/* ── Drawer pane (the aside hosting TaskSurface, OD-P3-10/11) ──
   The generic .drawer / .drawer-modal-root / .drawer-scrim / .drawer-modal.drawer-sheet /
   .drawer-modal.drawer-fullscreen chrome now lives in styles/drawer.css (loaded globally
   in main.tsx) — the Signal composer/record hosts are mounted at the shell root, outside
   this route-scoped stylesheet, and need the same chrome. Only Task-specific extensions
   (the .dw-* selectors below) stay here. */
/* The modal drawer fills its sheet/fullscreen container (pinned head + scroll body + foot). */
.drawer-modal .dw-surface { flex: 1; min-height: 0; border: 0; border-radius: 0; }
/* Mobile (<768px): ≥44px touch targets + a horizontally-scrollable tab strip. */
.drawer-modal.drawer-fullscreen .dw-iconbtn { width: 44px; height: 44px; }
.drawer-modal.drawer-fullscreen .dw-tabs { overflow-x: auto; flex-wrap: nowrap; }
.drawer-modal.drawer-fullscreen .dw-tab { min-height: 44px; white-space: nowrap; }
.drawer-modal.drawer-fullscreen .btn-ghost-danger,
.drawer-modal.drawer-fullscreen .checklist-checkbox { min-height: 44px; }

/* ── Toolbar ── (mockup `.toolbar`: view-tabs · spacer · segment · chips · search) */
.toolbar {
  display: flex; align-items: center; gap: 8px; flex-wrap: wrap; padding: 8px 12px;
  border-bottom: 1px solid var(--border);
}
.tb-spacer { flex: 1 1 0; min-width: 8px; }

/* F-A / OD-REDESIGN-61: member phones see work before configuration. The
   existing toolbar remains the one options surface; only its disclosure chrome
   is added for the least-technical mobile persona. */
.mobile-task-options {
  border-bottom: 1px solid var(--border);
  background: var(--card);
}
.mobile-task-options-trigger {
  display: flex; align-items: center; width: 100%; min-height: 44px;
  padding: 0 12px; border: 0; background: transparent; color: var(--foreground);
  font: inherit; font-size: 15px; font-weight: 600; text-align: left; cursor: pointer;
}
.mobile-task-options-trigger:hover { background: var(--secondary); }
.mobile-task-options-trigger:focus-visible { outline: 2px solid var(--ring); outline-offset: -2px; }
.mobile-task-options-summary { margin-left: 4px; color: var(--muted-foreground); font-weight: 500; }
.mobile-task-options-chevron {
  display: block; margin-left: auto; color: var(--muted-foreground);
  transition: transform 150ms ease;
}
.mobile-task-options-chevron--open { transform: rotate(180deg); }
.mobile-task-options-panel .toolbar { border-bottom: 0; }
@media (prefers-reduced-motion: reduce) {
  .mobile-task-options-chevron { transition: none; }
}

/* View-tabs inside the toolbar: the shared ViewTabs primitive defaults to the
   full-width sticky strip (the dashboard placement — view-tabs.css); here it sits
   INLINE as the first toolbar item, so the strip chrome (padding/border/sticky/
   background) is reset. The tab grammar (muted → brand-navy-text + the brand-orange
   underline) is shared and untouched. */
.toolbar .view-tabs {
  padding: 0;
  border-bottom: 0;
  position: static;
  background: transparent;
  z-index: auto;
}

/* Chip-style filter control (mockup `.chip`): bordered pill = label + current value
   + ▾; a transparent native <select> overlay preserves full filter capability + a11y. */
.chip {
  position: relative; display: inline-flex; align-items: center; gap: 6px;
  height: 32px; padding: 0 10px;
  border: 1px solid var(--input); border-radius: var(--radius-sm); /* 8px — control, OD-P3-10 */
  background: var(--background); font-size: 15px; color: var(--secondary-foreground); cursor: pointer;
}
.chip:hover { border-color: var(--border-strong); }
.chip:focus-within { outline: 2px solid var(--ring); outline-offset: 1px; }
.chip .ch-k { color: var(--muted-foreground); }
.chip .ch-v { color: var(--foreground); font-weight: 500; max-width: 120px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.chip .chip-chev { color: var(--muted-foreground); pointer-events: none; flex: none; }
/* The native select sits invisibly over the chip — clicks open the native menu. */
.chip-select { position: absolute; inset: 0; width: 100%; height: 100%; opacity: 0; cursor: pointer; font-size: 15px; border: 0; }

.seg { display: inline-flex; height: 32px; padding: 3px; background: var(--secondary); border-radius: var(--radius-sm); /* 8px — control, OD-P3-10 */ }
.seg-btn {
  border: 0; background: transparent; font: inherit; font-size: 15px; padding: 0 10px;
  border-radius: calc(var(--radius-sm) - 2px); /* inner control corner OD-P3-10 */
  color: var(--secondary-foreground); cursor: pointer; white-space: nowrap;
}
/* Active segment: crisp 1px ring + lift so it's clearly "the one that's on"
   against the grey track (no layout shift — ring drawn via box-shadow). */
.seg-btn-on {
  background: var(--background); font-weight: 600;
  box-shadow: 0 0 0 1px var(--border-strong), 0 1px 2px color-mix(in srgb, var(--ds-font-color-primary) 18%, transparent);
}
.search-mini {
  height: 32px; display: inline-flex; align-items: center; gap: 6px; padding: 0 10px;
  border: 1px solid var(--input); border-radius: var(--radius-sm); /* 8px — control, OD-P3-10 */
  color: var(--muted-foreground);
  font-size: 15px; min-width: 180px;
}
.search-input { border: none; outline: none; background: transparent; font: inherit; font-size: 15px; color: var(--foreground); width: 100%; }
.search-input::placeholder { color: var(--muted-foreground); }
.archived-toggle {
  display: inline-flex; align-items: center; gap: 6px; height: 32px; padding: 0 10px;
  border: 1px solid var(--input); background: var(--background);
  border-radius: var(--radius-sm); /* 8px — control, OD-P3-10 */
  font-size: 15px; cursor: pointer; color: var(--foreground);
}
/* Custom checkbox (DESIGN.md §5 checkbox spec) so 'Show archived' reads as a deliberate
   control, not a raw native checkbox — consistent with the other toolbar pills. */
.archived-checkbox {
  appearance: none; -webkit-appearance: none; width: 16px; height: 16px; cursor: pointer;
  border: 1.5px solid var(--input); border-radius: 4px; background: var(--background);
  display: inline-grid; place-content: center; flex: none; margin: 0;
}
.archived-checkbox:checked { background: var(--primary); border-color: var(--primary); }
