/* ── Tasks table + split-view shell styles (PR-B) ──────────────────────────────
   Extracted from TasksPage's inline <style> so both the standalone full-page
   host AND the split-view shell render identically. Every value resolves to a
   DESIGN.md token; the only literal px are layout dimensions (sizes/radii) and
   the documented drawer width clamp (OD-P3-2).
   ──────────────────────────────────────────────────────────────────────────── */

/* ── Page head ── */
/* IA-1: the page head is the shared shell/PageHead.tsx (title + meta beside it, full-bleed —
   no maxWidth cap). The bespoke .page-head-row / .tasks-page-title / .tasks-count-line
   classes were removed; only the head-owned controls below remain. */

/* ── Content header (mockup `.content-header`) ──────────────────────────────────
   The list/DB-view header chrome: a single clean row = entity icon + title +
   count pill + right-aligned inline action. Pixel oracle:
   docs/design-mockups/ui-revamp/mock-shell-and-table.html `.content-header`.
   Every value resolves to a DESIGN.md token (crosswalk of the mockup's --ds-*). */
.content-header {
  display: flex; align-items: center; gap: 10px;
  min-height: 48px; margin-bottom: 16px;
  padding-bottom: 14px; border-bottom: 1px solid var(--border);
}
.content-header .ch-icon { color: var(--muted-foreground); display: inline-flex; flex: none; }
.content-header .ch-title {
  font-weight: 600; font-size: 24px; letter-spacing: -0.01em; color: var(--foreground);
  margin: 0; line-height: 1.2;
}
/* Count pill (mockup `.ch-count`) — small muted pill on the tertiary surface. */
.content-header .ch-count {
  font-size: 11px; font-weight: 600; color: var(--muted-foreground);
  background: var(--secondary); padding: 2px 9px; border-radius: 999px;
  flex: none; line-height: 1.4;
}
/* Overdue/blocked subtotals + clearable filter chips ride just after the pill. */
.content-header .ch-meta { display: inline-flex; align-items: center; gap: 10px; flex-wrap: wrap; }
/* Right-aligned inline action (mockup `.ch-action`) — pushed to the far edge. */
.content-header .ch-action { margin-left: auto; flex: none; }
/* Off-track subtotals (blocked / overdue) ride beside the count pill. */
.ch-submeta { color: var(--muted-foreground); font-size: 15px; }

/* ── Split-view grid (the push/squash master-detail, ADR-0007) ── */
.split {
  display: grid;
  grid-template-columns: minmax(0, 1fr) clamp(360px, 33vw, 480px); /* OD-P3-2 drawer width; minmax(0,1fr) not bare 1fr so wide card/table content can't stretch the track past the viewport (min-width:auto blowout) */
  align-items: start; gap: 12px;
  /* CONV (owner-directed 2026-06-17): the data workspace runs FULL-BLEED — no max-width cap.
     It fills PageFrame's 24px gutters, which equal the topbar's px-6 gutter, so the table's
     right edge aligns with the account chip (no detached 1/3-width content on wide monitors).
     Only the Task column (1fr) absorbs the extra width; the other columns are fixed-px, so
     nothing balloons. A generous safety cap guards absurd ultra-wide Task columns only. */
  max-width: 1760px;
}
.split.nodrawer { grid-template-columns: minmax(0, 1fr); }
/* Expanded focus mode: table hidden, drawer fills the row. */
.split.expanded { grid-template-columns: 1fr; }
.split.expanded .assembly { display: none; }

/* ── Card assembly (OD-P3-10/11) ── */
.assembly {
  background: var(--card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); /* 12px — card surface, OD-P3-10 */
  box-shadow: var(--shadow-rest); /* OD-P3-11 resting lift */
  overflow: hidden; min-width: 0;
}

/* ── Drawer pane (the aside hosting TaskSurface, OD-P3-10/11) ──
   The generic .drawer / .drawer-modal-root / .drawer-scrim / .drawer-modal.drawer-sheet /
   .drawer-modal.drawer-fullscreen chrome now lives in styles/drawer.css (loaded globally
   in main.tsx) — the Signal composer/record hosts are mounted at the shell root, outside
   this route-scoped stylesheet, and need the same chrome. Only Task-specific extensions
   (the .dw-* selectors below) stay here. */
/* The modal drawer fills its sheet/fullscreen container (pinned head + scroll body + foot). */
.drawer-modal .dw-surface { flex: 1; min-height: 0; border: 0; border-radius: 0; }
/* Mobile (<768px): ≥44px touch targets + a horizontally-scrollable tab strip. */
.drawer-modal.drawer-fullscreen .dw-iconbtn { width: 44px; height: 44px; }
.drawer-modal.drawer-fullscreen .dw-tabs { overflow-x: auto; flex-wrap: nowrap; }
.drawer-modal.drawer-fullscreen .dw-tab { min-height: 44px; white-space: nowrap; }
