/* ════════════════════════════════════════════════════════════════════════════
   HomePage — layout only (Task 4.4/§4.5). Two stacked KPI rows (finance row is
   role-guarded and absent entirely for non-finance/admin viewers) reflowing
   auto-fit 160px→1fr, a FreshnessLabel, then the MyWeekPanel below. Token-only
   (DESIGN.md spacing scale) — mirrors sales-dashboard-page.css's KPI grid.
   ════════════════════════════════════════════════════════════════════════════ */
.home-kpi-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 12px;
  margin-bottom: 12px;
}

.home-kpi-grid + .freshness-label {
  display: inline-block;
  margin-bottom: 16px;
}

/* Link wrapper around each KPITile: no underline/color-bleed onto the tile's own
   text colors (KPITile owns its own foreground/muted-foreground) — the anchor is
   purely the drill-target hit area (no-bleed, mirrors .mini-name-chip). */
.home-kpi-link {
  display: block;
  color: inherit;
  text-decoration: none;
  min-width: 0;
}

/* Jump-affordance fix — the PageHead "Needs attention · N →" summary (personal-first order,
   AC-513) must READ as a link, not just behave like one. Same underline+color grammar as the
   other inline text-links in the app. */
.home-attention-jump {
  color: var(--primary);
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 2px;
}
.home-attention-jump:hover {
  color: var(--brand-navy-text);
}
.home-attention-jump:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

/* ════════════════════════════════════════════════════════════════════════════
   Home two-region wrapper (Step 5, OD-REDESIGN-18, AC-515). The Attention brief
   and the Personal canvas are emitted in DOM in the user-chosen order — this
   wrapper is a plain block-flow column and MUST NEVER use CSS `order` or
   `flex-direction: column-reverse`/media-query reflow to visually reorder the
   two regions against their DOM order (Rule 9). Only density/disclosure inside
   each region may adapt at ≤390px, never the region order itself.
   ════════════════════════════════════════════════════════════════════════════ */
.home-regions {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.home-personal-canvas {
  display: flex;
  flex-direction: column;
}

/* ════════════════════════════════════════════════════════════════════════════
   RI-2 (Q2/Rule 8, ratified Option B) — the ≤390px order-toggle disclosure.
   Mirrors TasksWorkspace.css's `.mobile-task-options` disclosure grammar (same
   44px+ trigger, chevron rotation, panel-below layout) but compact + right-
   aligned (not a full-width toolbar row) — the toggle must never be the lead
   element ahead of the attention brief on a phone. Token-only (DESIGN.md).
   ════════════════════════════════════════════════════════════════════════════ */
.home-order-disclosure {
  display: flex;
  justify-content: flex-end;
  margin-bottom: 12px;
}
.home-order-trigger {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 40px;
  padding: 0 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--card);
  color: var(--foreground);
  font: inherit;
  font-size: 13.5px;
  font-weight: 600;
  cursor: pointer;
}
.home-order-trigger:hover {
  background: var(--secondary);
}
.home-order-trigger:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}
.home-order-summary {
  color: var(--muted-foreground);
  font-weight: 500;
}
.home-order-chevron {
  color: var(--muted-foreground);
  transition: transform 150ms ease;
}
.home-order-chevron--open {
  transform: rotate(180deg);
}
.home-order-panel {
  margin-top: 8px;
}
/* The panel hosts the radiogroup inline (not the sticky full-width strip
   placement) — reset that chrome, mirroring the toolbar's `.view-tabs` reset. */
.home-order-panel .view-tabs {
  position: static;
  padding: 0;
  border-bottom: 0;
  background: transparent;
  justify-content: flex-end;
}
@media (prefers-reduced-motion: reduce) {
  .home-order-chevron { transition: none; }
}

