.home-order-trigger:hover {
  background: var(--secondary);
}
.home-order-trigger:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}
.home-order-summary {
  color: var(--muted-foreground);
  font-weight: 500;
}
.home-order-chevron {
  color: var(--muted-foreground);
  transition: transform 150ms ease;
}
.home-order-chevron--open {
  transform: rotate(180deg);
}
.home-order-panel {
  margin-top: 8px;
}
/* The panel hosts the radiogroup inline (not the sticky full-width strip
   placement) — reset that chrome, mirroring the toolbar's `.view-tabs` reset. */
.home-order-panel .view-tabs {
  position: static;
  padding: 0;
  border-bottom: 0;
  background: transparent;
  justify-content: flex-end;
}
@media (prefers-reduced-motion: reduce) {
  .home-order-chevron { transition: none; }
}

text:
/* ════════════════════════════════════════════════════════════════════════════
   StackedUnionHome — the stacked-union cockpit layout (Issue E).
   Phone-first: sections stack vertically on a single scrollable surface; the money
   KPI grid reflows auto-fit (reuses .home-kpi-grid). Token-only (DESIGN.md scale).
   No fixed widths → no horizontal scroll on ≤380px.
   ════════════════════════════════════════════════════════════════════════════ */

/* Each role-scope section — a stacked block with breathing room between scopes. */
.home-stack-section {
  margin-bottom: 28px;
}
.home-stack-section:last-child {
  margin-bottom: 0;
}

/* Section heading block (the role-scope label — "Whole-company cockpit", "[BU] — function
   cockpit", "My Week"). Overline-style subtitle, title carries the scope name. */
.home-stack-section-head {
  margin: 4px 2px 12px;
}
.home-stack-section-title {
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--foreground);
  margin: 0;
  line-height: 1.25;
}
.home-stack-section-subtitle {
  font-size: 13px;
  color: var(--muted-foreground);
  margin: 4px 0 0;
}

/* A cockpit sub-section (money-position / ops-KPI) sits inside a cockpit section. */
.home-stack-subsection {
  margin-bottom: 14px;
}
.home-stack-subsection-title {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted-foreground);
  margin: 0 2px 8px;
}

/* Slot — a quiet bordered box for a parallel-slice drop point (AR tile / BU money / AP strip /
   ops-KPI coming). Dashed border signals "drop point / coming"; solid muted for read-only strips. */
.home-stack-slot {
  border: 1px dashed var(--border);
  border-radius: 8px;
  background: var(--muted);
  padding: 12px 16px;
  margin: 8px 0;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 16px;
  min-height: 0;
}
.home-stack-slot--muted {
  border-style: solid;
}
.home-stack-slot--placeholder {
  min-height: 48px;
}
.home-stack-slot-label {
  font-size: 14px;
  color: var(--muted-foreground);
  flex: 1 1 160px;
  min-width: 0;
}
.home-stack-slot-link {
  font-size: 14px;
  font-weight: 600;
  color: var(--primary);
  text-decoration: none;
  white-space: nowrap;
  flex: 0 0 auto;
}

/* Cascade drill — a one-line link reusing /work/cascade. */
.home-stack-cascade-drill {
  margin: 10px 2px 0;
}
.home-stack-cascade-drill a {
  font-size: 14px;
  font-weight: 600;
  color: var(--primary);
  text-decoration: none;
}

/* Capture-first CTA — the contributor's dominant one-tap capture entry (→ /ops/new). */
.home-stack-capture-cta {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  padding: 14px 20px;
  margin-bottom: 14px;
  border-radius: 10px;
  background: var(--primary);
  color: var(--primary-foreground);
  font-size: 16px;
  font-weight: 600;
  text-decoration: none;
  box-shadow: var(--shadow-rest);
}
.home-stack-capture-cta:hover {
  filter: brightness(0.97);
}

/* Error banner (directory load failure). */
.home-stack-error {
  border: 1px solid var(--destructive);
  color: var(--destructive);
  background: color-mix(in srgb, var(--destructive) 6%, transparent);
  border-radius: 8px;
  padding: 12px 16px;
  margin-bottom: 16px;
  font-size: 15px;
}

/* Phone (≤380px): the KPI grid reflows 2-up (160px min × 2 + gap ≈ 332px < 380px); sections +
   slots are full-width block, no horizontal scroll. No media query needed — auto-fit + block flow
   handle it. This guard tightens the capture CTA + slots to the narrow viewport. */
@media (max-width: 380px) {
  .home-stack-section-title {
    font-size: 17px;
  }
  .home-stack-slot {
    padding: 10px 12px;
  }
}

