text:
/* SignalComposer — the FB-style capture-minimal panel (PORT convergence `sigComposer` @ the
   e7 visual bar, design-review step-4 CRITICAL-1). Panel padding + vertical rhythm, labeled
   fields with real space between label and value (MINOR-7/8), and a bordered foot row. */
.signal-composer {
  display: flex; flex-direction: column; gap: 12px; padding: 16px;
}

/* The composer's mention popover anchors to the textarea, so the wrapper is the positioning
   context for the absolutely-positioned SignalMentionPicker (replaces an inline style — house
   pattern is a class in a co-located stylesheet). */
.signal-composer-mention-anchor {
  position: relative;
}
.signal-composer-mention-anchor textarea {
  width: 100%; min-height: 96px; padding: 12px;
  border: 1px solid var(--border); border-radius: var(--radius-lg);
  background: var(--card); font: inherit; font-size: 14px; color: var(--foreground);
  resize: vertical; line-height: 1.5;
}
.signal-composer-mention-anchor textarea::placeholder { color: var(--text-light); }
.signal-composer-mention-anchor textarea:focus-visible {
  outline: 2px solid var(--ring); outline-offset: 1px; border-radius: var(--radius-lg);
}

.signal-composer-row { display: flex; align-items: flex-start; gap: 12px; flex-wrap: wrap; }
.signal-composer-row > * { flex: 1; min-width: 180px; }

/* datetime-local has no equivalent styled kit primitive (TextInput/Select), so the label +
   box are styled directly here — mirrors the kit's own label-above-box rhythm (Select.css). */
.signal-composer-datetime { display: flex; flex-direction: column; gap: 4px; }
.signal-composer-field-label {
  font-size: 12px; color: var(--muted-foreground); font-weight: 500;
}
.signal-composer-datetime input {
  display: block; width: 100%; height: 32px; padding: 0 10px; box-sizing: border-box;
  background: var(--background); border: 1px solid var(--input);
  border-radius: var(--radius-sm); font: inherit; font-size: 15px; color: var(--foreground);
}
.signal-composer-datetime input:focus-visible {
  outline: 2px solid var(--ring); outline-offset: 2px;
}

.signal-composer-pill {
  display: inline-flex; align-items: center; gap: 5px; height: 24px; padding: 0 8px;
  border-radius: var(--radius-pill); background: var(--secondary); color: var(--muted-foreground);
  font-size: 11.5px; width: fit-content;
}

.signal-composer-author,
.signal-composer-vis {
  margin: 0; font-size: 12px; color: var(--muted-foreground);
}

.signal-composer-foot {
  display: flex; align-items: center; gap: 8px; padding-top: 12px;
  border-top: 1px solid color-mix(in srgb, var(--border) 70%, transparent);
}
.signal-composer-foot .muted-2 { flex: 1; min-width: 0; font-size: 12px; color: var(--muted-foreground); }

